#pragma once

#include <string>
#include <string_view>

namespace ember::unicode {

// Just the Unicode the tokenizers need, from tables generated by scripts/gen_unicode_tables.py
// (Unicode 16.0, the version Hugging Face's tokenizers library uses).
//
// Text comes in as UTF-8 that nobody checked. A byte that is not part of a valid character is kept
// as a code point of its own above U+10FFFF, kInvalidByteBase + the byte, so it survives every step
// and goes back out as the same byte. It is not a letter, number, or space, and NFC leaves it
// alone.
inline constexpr char32_t kInvalidByteBase = 0x110000;

// UTF-8 to code points, keeping invalid bytes as above.
std::u32string Decode(std::string_view utf8);
// Code points back to UTF-8, invalid bytes back to themselves.
std::string Encode(std::u32string_view text);

bool IsLetter(char32_t c);      // general category L*, regex \p{L}
bool IsNumber(char32_t c);      // general category N*, regex \p{N}
bool IsWhiteSpace(char32_t c);  // the White_Space property, regex \s

// Unicode Normalization Form C: canonical decomposition, canonical ordering, then canonical
// composition, as in UAX #15.
std::u32string Nfc(std::u32string_view text);

// UTF-8 with each broken sequence replaced by one U+FFFD, the way Rust's String::from_utf8_lossy
// does it (a "maximal subpart" per replacement).
std::string Lossy(std::string_view bytes);

}  // namespace ember::unicode
